mapper.select:
SELECT  TO_CHAR(NVL(T.UNIT_VALUE_T,0),'FM9999999999999999.0000')  unitValue,
	   TO_CHAR(NVL(T.UNIT_VALUE,0),'FM9999999999999999.0000') unitValueT ,
FROM REP_PROD_INFO INFO
		 INNER JOIN REP_PROD_INDEX PRI ON PRI.PROD_ID = NVL(INFO.P_PROD_ID,INFO.PROD_ID) AND PRI.STATUS = 'E'
WHERE INFO.PROD_ID = #{prodId}
  AND PRI.VALUE_DATE = #{lastWorkDay}
